def is_power_of_five(X):
    if X <= 0:
        return False

    # Check if X is exactly 1 (5^0). Since we expect X >= 5, this might not trigger, but it's good practice.
    if X == 1:
        return True

    while X > 1 and X % 5 == 0:
        X //= 5

    return X == 1

results = {}
for n in range(3, 16):
    X = (2**n) - 3

    is_power = is_power_of_five(X)

    if is_power:
        # Find the exponent k such that 5^k = X
        k = 0
        temp_X = X
        while temp_X > 1:
            temp_X //= 5
            k += 1
        results[n] = k
    else:
        # Verification part: Confirm it's not a power of 5. 
        # The is_power_of_five function already verifies this implicitly by returning False 
        # if the remaining factor after division by 5 is not 1.
        # We record a note for verification.
        results[n] = "Not a power of 5"

print("Results for n = 3 to 15:")
for n, result in results.items():
    print(f"n={n}: X = 2^{n} - 3 = { (2**n) - 3 } -> {result}")

