def check_case(k):
    """Checks if 5^k + 3 is a power of 2."""
    target = 5**k + 3

    # Check if target is a power of 2
    if target <= 0:
        return False, None

    is_power_of_two = (target > 0) and ((target & (target - 1)) == 0)

    if is_power_of_two:
        # Find n such that 2^n = target
        n = target.bit_length() - 1
        # We must ensure n >= 3
        if n >= 3:
            return True, n
        else:
            return False, n # Should not happen for k>=1
    else:
        return False, None

