def is_power_of_five(X):
    """Checks if a positive integer X is a power of 5."""
    if X <= 0:
        return False
    while X > 1:
        if X % 5 != 0:
            return False
        X //= 5
    return True

solutions = []
for n in range(3, 31):
    X = (2**n) - 3
    if is_power_of_five(X):
        solutions.append(n)

print(f"Solutions found in the range 3 <= n <= 30: {solutions}")
print(f"Number of solutions: {len(solutions)}")

def check_power_of_5(number):
    if number <= 0:
        return False
